  window.I18N_DETAIL = window.I18N_DETAIL || {}; window.I18N_DETAIL["sk"] = {"detail_tab_details":"Detaily produktu","detail_tab_specs":"Špecifikácie","detail_tab_care":"Používanie a starostlivosť","detail_tab_shipping":"Doručovanie a ochrana osobných údajov","detail_tab_faq":"Často kladené otázky","detail_pack":"Veľkosť balenia","detail_weight":"Hmotnosť položky","detail_origin":"Vyrobila spoločnosť","detail_packaging":"Balené ako","care_clean_title":"Čistenie","care_clean_body":"Po každom použití opláchnite pod teplou vodou a nechajte úplne vyschnúť na vzduchu. Nepoužívajte čistiace prostriedky na báze alkoholu a nenechávajte kefku namočenú – oboje časom poškodzuje povrch.","care_store_title":"Pamäť","care_store_body":"Uchovávajte ich na suchom a tmavom mieste, mimo dosahu priameho slnečného žiarenia a tepla. Mäkké puzdro alebo originálna škatuľa chránia okuliare medzi jednotlivými použitiami pred prachom a poškriabaním.","care_battery_title":"Nabíjací výkon:","care_battery_body":"Pred prvým použitím ho úplne nabite a ak nebol používaný dlhšie ako mesiac, doplňte ho. Ak model používa batérie, pred dlhodobým uskladnením ich vyberte.","care_lube_title":"S mazivom","care_lube_body":"Lubrikant na vodnej báze je bezpečnou voľbou pre silikónové povrchy. Lubrikanty na báze silikónu môžu časom ovplyvniť niektoré materiály, preto si pred ich použitím overte ich vhodnosť.","ship_pack_title":"Diskrétne balenie","ship_pack_body":"Každá objednávka sa odosiela v obyčajnom, neoznačenom obale s neutrálnym názvom produktu na štítku. Nič na vonkajšej strane neodhaľuje, čo je vo vnútri.","ship_time_title":"Čas odoslania","ship_time_body":"Objednávky zadané do 14.00 hod. v pracovný deň sa vyzdvihnú a odošlú v ten istý deň. Doručenie zvyčajne trvá 3 až 7 pracovných dní v závislosti od miesta určenia.","ship_privacy_title":"Ochrana osobných údajov","ship_privacy_body":"Vaše meno sa nikdy neobjaví na prepravnom štítku a marketingové správy vám posielame len vtedy, ak o ne požiadate. Záznamy z živého chatu sa uchovávajú len tak dlho, ako je potrebné na zodpovedanie vašej otázky.","faq_q1":"Zmestí sa do môjho boxu na balíky?","faq_a1":"Áno. Vyššie uvedené rozmery sú skutočné rozmery zabaleného produktu, nie vonkajšej krabice, v ktorej ho odosielame.","faq_q2":"Môžem ho používať s lubrikantom?","faq_a2":"Áno, s lubrikantom na vodnej báze. V časti Používanie a starostlivosť sa dozviete, ktorý typ sa k tomuto materiálu najlepšie hodí.","faq_q3":"Je názov produktu na faktúre uvedený diskrétne?","faq_a3":"Áno. Na faktúrach a dodacích listoch sa používa neutrálny názov produktu a na vonkajšej krabici nie je žiadna značka.","rel_title":"Môže vás ešte zaujímať"};
