  window.I18N_DETAIL = window.I18N_DETAIL || {}; window.I18N_DETAIL["hr"] = {"detail_tab_details":"Detalji artikla","detail_tab_specs":"Specifikacije","detail_tab_care":"UPORABA I ODRŽAVANJE","detail_tab_shipping":"Dostava i privatnost","detail_tab_faq":"Česta pitanja","detail_pack":"Veličina pakiranja","detail_weight":"Težina artikla","detail_origin":"Proizvedeno u","detail_packaging":"Pakirano kao","care_clean_title":"Čišćenje","care_clean_body":"Nakon svake upotrebe isperite toplom vodom i ostavite da se potpuno osuši na zraku. Nemojte upotrebljavati sredstva za čišćenje na bazi alkohola i nemojte je ostavljati da se namače — oboje s vremenom oštećuje površinu.","care_store_title":"Skladištenje","care_store_body":"Čuvajte ga na suhom i tamnom mjestu, daleko od izravne sunčeve svjetlosti i topline. Mekana vrećica ili originalna kutija štite od prašine i ogrebotina između upotreba.","care_battery_title":"Maksimalna snaga punjenja","care_battery_body":"Prije prve uporabe napunite ga do kraja, a ako nije bio u uporabi dulje od mjesec dana, dopunite ga. Ako model radi na baterije, izvadite ih prije dugotrajnog skladištenja.","care_lube_title":"S mazivom","care_lube_body":"Lubrikant na bazi vode siguran je izbor za silikonske površine. Lubrikanti na bazi silikona s vremenom mogu utjecati na neke materijale, stoga provjerite prije nego što ih upotrijebite.","ship_pack_title":"Diskretna ambalaža","ship_pack_body":"Svaka se narudžba šalje u običnoj, neoznačenoj ambalaži s neutralnim nazivom proizvoda na etiketi. Ništa na vanjskoj strani ne otkriva što se nalazi unutra.","ship_time_title":"Vrijeme slanja","ship_time_body":"Narudžbe poslane prije 14 h na radni dan pripremaju se i otpremaju istog dana. Dostava obično traje 3 – 7 radnih dana, ovisno o odredištu.","ship_privacy_title":"Zaštita privatnosti","ship_privacy_body":"Vaše ime nikada se ne pojavljuje na naljepnici za otpremu, a marketinške poruke šaljemo samo ako ih zatražite. Zapisi razgovora uživo čuvaju se samo onoliko dugo koliko je potrebno da odgovorimo na vaše pitanje.","faq_q1":"Hoće li stati u moj pretinac za pakete?","faq_a1":"Yes. The dimensions above are the actual packed measurements of the product, not the outer box we ship it in.","faq_q2":"Mogu li ga upotrebljavati s lubrikantom?","faq_a2":"Da, s lubrikantom na bazi vode. U odjeljku „Uporaba i održavanje” objašnjeno je koja vrsta najbolje odgovara ovom materijalu.","faq_q3":"Is the product name discreet on the invoice?","faq_a3":"Yes. Invoices and packing slips use a neutral product name, and the outer box carries no branding.","rel_title":"Možda će vam se također svidjeti"};
